import{_ as t,o,c as e,a2 as r}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"《神造物·火种》故事概要","description":"","frontmatter":{},"headers":[],"relativePath":"中层/历史/火种故事.md","filePath":"中层/历史/火种故事.md","lastUpdated":null}'),l={name:"中层/历史/火种故事.md"};function h(i,a,n,u,s,q){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="《神造物·火种》故事概要" tabindex="-1">《神造物·火种》故事概要 <a class="header-anchor" href="#《神造物·火种》故事概要" aria-label="Permalink to &quot;《神造物·火种》故事概要&quot;">​</a></h1><blockquote><p>《神造物·火种》是聚焦于黑暗时代早期（约黑暗时代 120 年）的故事，上篇讲述毁灭神登神之前，不同种族的普通生灵在压迫中存续、相遇、并点燃第一簇反抗火种的故事；下篇则讲述了一个关于如何面对&quot;代价&quot;的故事。</p></blockquote><h2 id="时代背景" tabindex="-1">时代背景 <a class="header-anchor" href="#时代背景" aria-label="Permalink to &quot;时代背景&quot;">​</a></h2><p>故事发生时，共同体已解体，新五族统治大陆，法师阶级垄断魔法、奴役平民。主角洛尔是黑暗时代的鹿族新生儿，父母在贱民区中早逝或失踪。他不知共同体、不知神明、不知鹿族曾是科研之族，只知道饿、只知道冷、只知道老爷们不能惹。</p><h2 id="上篇-觉醒与逃亡" tabindex="-1">上篇：觉醒与逃亡 <a class="header-anchor" href="#上篇-觉醒与逃亡" aria-label="Permalink to &quot;上篇：觉醒与逃亡&quot;">​</a></h2><h3 id="洛尔的逃亡" tabindex="-1">洛尔的逃亡 <a class="header-anchor" href="#洛尔的逃亡" aria-label="Permalink to &quot;洛尔的逃亡&quot;">​</a></h3><p>洛尔的魔力第一次失控后，贱民区的告密者向老爷们举报了他——魔力觉醒意味着死刑。洛尔被迫逃亡，独自进入荒野。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../世界/地脉与魔法">地脉与魔法</a></p></blockquote><h3 id="熊族的枪与星" tabindex="-1">熊族的枪与星 <a class="header-anchor" href="#熊族的枪与星" aria-label="Permalink to &quot;熊族的枪与星&quot;">​</a></h3><p>洛尔在逃亡途中误入废弃的共同体哨站遗址，遇到正在寻找什么的熊族潜伏者<strong>米哈伊尔</strong>。米哈伊尔用枪指着洛尔，大骂&quot;罪人&quot;——他记恨鹿族当年在神殿干的事。洛尔的困惑是真诚的，他不知道什么是&quot;神殿&quot;。米哈伊尔逐渐意识到这个鹿族不是装傻，态度从敌意转为一种粗粝的叹息，并开始教洛尔生存与战斗技巧。</p><p>某夜篝火旁，米哈伊尔擦着一枚褪色的红星徽章，用漫不经心的语气讲起共同体：电灯、铁路、人民的军队。茫然的洛尔问&quot;电灯是什么&quot;，米哈伊尔颇感讽刺——发明电灯的种族此刻却连电灯是什么都不知道了。</p><p>兽潮逼近一片贱民窝棚区时，米哈伊尔的第一反应是离开——他是潜伏者，任务第一。但弯腰捡起掉落的共同体徽章后，他盯着上面的五角星静止了几秒，骂了一声&quot;妈的&quot;，攥紧徽章转向兽潮。他引开兽群、为平民而死，临死前将包裹与徽章交给洛尔，嘱托他完成任务。</p><h3 id="废墟中的狼" tabindex="-1">废墟中的狼 <a class="header-anchor" href="#废墟中的狼" aria-label="Permalink to &quot;废墟中的狼&quot;">​</a></h3><p>洛尔在窝棚区遇到小狼<strong>格雷</strong>——浑身是伤、脚踝有新鲜的枷锁勒痕，刚从奴隶营逃出。格雷是乐天派，饿着肚子会把干粮分给别人。他的善良不是美德，是基因锁让他只能这样；但洛尔不知道基因锁的存在，只觉得这个狼族傻傻的、挺可爱。格雷跟着洛尔走，只因为&quot;你一个人走不安全，我陪你&quot;。</p><h3 id="宴会的血与储藏室的光" tabindex="-1">宴会的血与储藏室的光 <a class="header-anchor" href="#宴会的血与储藏室的光" aria-label="Permalink to &quot;宴会的血与储藏室的光&quot;">​</a></h3><p>洛尔与格雷被捕奴队抓获，押送进一个法师老爷的宅邸。宴会上，洛尔看到新五族法师们分食智慧生灵的尸体，几乎魔力失控——他以为桌上的尸体是格雷。一位法师按住了他的肩膀，低声说&quot;你要干嘛，老实点，回去&quot;。那眼神不是威胁，是像在赶走一只快被碾到的虫子。</p><p>格雷还活着——是那位法师以&quot;宠物&quot;的名义把他单独调走了。</p><p>洛尔开始注意这位法师不对劲。某个夜晚他误入内院，撞见那个趾高气昂的法师老爷正面无表情地站在墙角，而平日里作为&quot;宠物&quot;的鹿族青年正瘫在躺椅上喝果汁——这是<strong>塞林</strong>，第一个成功运用精神控制的鹿族。他控制法师不是为了推翻暴政，只是想过好日子。他教洛尔感知、压制、引导魔力，并平淡地道出法师食人的秘密：那是顶级法师的必经之路。</p><p>危机爆发时，塞林不再逃避。他超载自己成为转接装置，让其余鹿族奴隶通过他编织精神控制的网络，一举控制了整栋府邸的高层。但代价已经埋下——塞林从此再也无法离开法师的地盘，他将自己从一个人，变成了一件工具。洛尔离开时，他摆了摆手：&quot;你们继续前进吧。我们的战场在这里。&quot;</p><h3 id="兔村——避难所的真相" tabindex="-1">兔村——避难所的真相 <a class="header-anchor" href="#兔村——避难所的真相" aria-label="Permalink to &quot;兔村——避难所的真相&quot;">​</a></h3><p>米哈伊尔死前曾告诉洛尔，走投无路可以去南方山林找兔村。洛尔完成米哈伊尔交代的任务后，带着格雷南下。兔族青年<strong>斯科克</strong>带他们入村。此时的兔村只是山林深处的窝棚群，住着几十个逃亡者。村边住着一位白发金瞳的女性——精灵族，从不与人交谈。</p><p>面见长老<strong>科伦</strong>时，洛尔才知道：捕奴队的动向、斯科克偷偷送的食物、逃亡者的存在——长老全都知道，一直在暗中打马虎眼，只是从不公开表态。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../表层/种族/兔族" class="layer-link" data-layer="表层">兔族</a></p></blockquote><h3 id="捕奴队——点燃火种" tabindex="-1">捕奴队——点燃火种 <a class="header-anchor" href="#捕奴队——点燃火种" aria-label="Permalink to &quot;捕奴队——点燃火种&quot;">​</a></h3><p>一支捕奴队向兔村逼近。有人想把引祸的新人交出去，洛尔站了出来：跑了，以后这里永远都会有捕奴队；只有打退他们，让他们觉得这里不值得来，才是真办法。战斗不大——只是一队捕奴队——但兔村赢了。人们第一次知道：法师不是不可战胜的，老爷们不是不能反抗的。洛尔成为兔村的第一代守护者。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../表层/历史/黑暗时代" class="layer-link" data-layer="表层">黑暗时代</a></p></blockquote><h2 id="下篇-48小时" tabindex="-1">下篇：48小时 <a class="header-anchor" href="#下篇-48小时" aria-label="Permalink to &quot;下篇：48小时&quot;">​</a></h2><p>洛尔的身体出了问题——他在变成格雷。格雷提出移植自己的颅核，洛尔激烈否决；格雷用他惯常的、讨论晚饭般的语气回应：&quot;你现在这样子走不到旧都的。你昨天差点撕了斯科克。你咬了我。下次你咬到别人怎么办？&quot;</p><p>颅核移植完成，格雷进入冬眠舱。<strong>艾莉芙</strong>交给洛尔一张地图和一个名字——伊芙琳：&quot;带她去神殿。告诉她，带上她自己。&quot;</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/艾莉芙">艾莉芙</a></p></blockquote><h3 id="酒馆里的精灵" tabindex="-1">酒馆里的精灵 <a class="header-anchor" href="#酒馆里的精灵" aria-label="Permalink to &quot;酒馆里的精灵&quot;">​</a></h3><p>洛尔在破酒馆找到<strong>伊芙琳</strong>。她趴在桌上睡觉，白发散乱，法杖斜靠桌沿。她告诉洛尔，她梦到过他。她使用魔法极为随意——她只能创造，不能改变：凭空造火源烧水，却无法直接让水热起来。</p><p>流传的故事中，精灵族能够掌管梦境。真相是：精灵能进入他人梦境并将梦境&quot;上传&quot;至世界树，世界树是精灵区分梦境与现实的锚点。与世界树单向断联后，绝大多数精灵陷入无法分辨梦与现实的疯狂，反复自杀试图从梦中醒来；而伊芙琳的应对方式是不再分辨——梦里也当真，现实也当真，上传每一个自己遇到的梦境，即使十传九假。</p><h3 id="走向旧都" tabindex="-1">走向旧都 <a class="header-anchor" href="#走向旧都" aria-label="Permalink to &quot;走向旧都&quot;">​</a></h3><p>洛尔的鹿角松动、脱落，毛色变浅，身体逐渐&quot;格雷化&quot;。驿站里没有人知道他是谁；一个狐族少女坐在他对面喝汤，从头到尾没有问他是谁——她默认了他是狼族。</p><h3 id="旧都神殿" tabindex="-1">旧都神殿 <a class="header-anchor" href="#旧都神殿" aria-label="Permalink to &quot;旧都神殿&quot;">​</a></h3><p>神殿深处，神明并非沉睡，而是被困——他在对抗某个只有他能压制的威胁，无法离开。洛尔转达了艾莉芙的质问：&quot;你为什么还避世不出？&quot;</p><p>但最糟糕的事情发生了：洛尔来晚了，身体已完全格雷化，没有属于自己的基因样本，神明无法复原他。神明手中只有一些来自共同体时期的碎片基因数据——不属于任何一个已知种族。</p><p>&quot;仅理论可行。你会变成什么样子，没人知道。&quot;</p><p>另一个选项是复制格雷的颅核——安全、确定。洛尔选了前者：他不能做一辈子的格雷，不能顶着格雷的身躯偷生。&quot;我是谁不重要。我做什么，才重要。&quot;</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/维斯塔">维斯塔</a>、<a href="./正传历史">正传历史</a></p></blockquote><h3 id="尾声" tabindex="-1">尾声 <a class="header-anchor" href="#尾声" aria-label="Permalink to &quot;尾声&quot;">​</a></h3><p>格雷醒来时，桌上放着那枚褪色的红星徽章，下面压着一张纸：</p><blockquote><p>&quot;格雷：你的颅核还给你了。这枚徽章是米哈伊尔的，现在它是你的。替我保管。我不回兔村了。我现在的样子——你不会认得的。你记得那晚你问我，电灯是什么吗？我没回答，但我现在知道了。电灯就是电灯。&quot;</p></blockquote><p>后来，兔村附近流传起一个都市怪谈：山林里有一只怪物，有时会在捕奴队逼近时发出声响引开他们，有时会在村口留下柴火和野果。只有格雷，在某个深夜，看着山洞口一串不属于任何种族的脚印，笑了。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/历史/黑暗时代" class="layer-link" data-layer="表层">黑暗时代</a></li><li><a href="./正传历史">正传历史</a></li><li><a href="./../世界/地脉与魔法">地脉与魔法</a></li><li><a href="./../世界/特殊地点">特殊地点</a></li><li><a href="./../../表层/种族/兔族" class="layer-link" data-layer="表层">兔族</a></li><li><a href="./../../表层/种族/精灵族" class="layer-link" data-layer="表层">精灵族</a></li><li><a href="./../人物/艾莉芙">艾莉芙</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li></ul>',48)])])}const c=t(l,[["render",h]]);export{d as __pageData,c as default};
